          outboxId: entry.id,
          orderId: entry.orderId,
          vendorId: entry.vendorId ?? null,
          userId: entry.userId,
          toEmail: entry.toEmail,
          subject: entry.subject,
          attempts: nextAttempt,
          error: errMsg
