function bucketKey(date7, granularity) {
  if (granularity === "yearly") return String(date7.getFullYear());
  if (granularity === "monthly") return date7.toISOString().slice(0, 7);
  if (granularity === "weekly") {
    const onejan = new Date(date7.getFullYear(), 0, 1);
    const week = Math.ceil(((date7.getTime() - onejan.getTime()) / 864e5 + onejan.getDay() + 1) / 7);
    return `${date7.getFullYear()}-W${String(week).padStart(2, "0")}`;
  }
  return date7.toISOString().slice(0, 10);
}
